import json
from pathlib import Path
P=Path(__file__).parent
nodes={r['id']:r for r in map(json.loads,(P/'nodes.jsonl').read_text().splitlines())}
edges={r['key']:r for r in map(json.loads,(P/'edges.jsonl').read_text().splitlines())}
reviews=[]
def node(id,verdict,reason,proposal):
 n=nodes[id];reviews.append({'kind':'node','id':id,'discipline':n['discipline'],'before':n['statement'],'sourceExcerpt':n['source'],'location':n['location'],'verdict':verdict,'reason':reason,'proposal':proposal,'reviewLevel':'model-semantic-review','sourceVerification':'stored-excerpt-only; original PDF not inspected','applied':False})
def edge(key,reason,proposal,verdict='revise-or-retype'):
 e=edges[key];reviews.append({'kind':'edge','id':key,'discipline':e['discipline'],'before':{'prerequisite':e['prerequisite'],'target':e['target'],'type':e['type'],'strength':e['strength'],'failure':e['failure']},'location':e['location'],'verdict':verdict,'reason':reason,'proposal':proposal,'reviewLevel':'model-semantic-review','sourceVerification':'stored endpoints and reasoning; no learner validation','applied':False})
