  direct=n['source'];node(n['id'],'restore-learning-action','把“学生实际完成行动”变成“复述学生应该做什么”，改变了测量对象。背出活动要求不能证明会做活动。源段若是教学建议，也不能伪装为强制课标达标项。','先核对源页所属栏目。若为内容要求，以原文学生行动为锚点：'+direct+'；若为教学建议，转入教学任务库并引用相应课标，不新增课标要求。')
